// NewDecidePayload builds a capability service decide endpoint payload.
func NewDecidePayload(body *DecideRequestBody, id int64, cookie string) *capability.DecidePayload {
	v := &capability.DecidePayload{
		Approve: *body.Approve,
		Note:    body.Note,
	}
	v.ID = id
	v.Cookie = cookie

	return v
}

